import { API_URL, USE_MOCK } from "@/lib/constants";
// Returns the PDF blob generated by the backend from saved records. Needs the secure access token (phase 4).
export async function fetchReportPdf(assessmentId: string, accessToken?: string): Promise<Blob> {
  if (USE_MOCK) throw new Error("unavailable");
  const res = await fetch(`${API_URL}/reports/${assessmentId}/pdf`, { headers: { Authorization: `Bearer ${accessToken ?? ""}` } });
  if (!res.ok) throw new Error("unavailable");
  return res.blob();
}
